head.b:skin:
/*
-----------------------------------------------
Blogger Template Style
Name:        Sky Blog
Author :     http://www.soratemplates.com
License:     Premium Version
----------------------------------------------- */

/* Variable definitions
====================
<Variable name="maincolor" description="Main Color" type="color" default="#00C0A8" value="#00C0A8"/>

*/

html,body,div,span,applet,object,iframe,h1,h2,h3,h4,h5,h6,p,blockquote,pre,a,abbr,acronym,address,big,cite,code,del,dfn,em,img,ins,kbd,q,s,samp,small,strike,strong,sub,sup,tt,var,b,u,i,center,dl,dt,dd,ol,ul,li,fieldset,form,label,legend,table,caption,tbody,tfoot,thead,tr,th,td,article,aside,canvas,details,embed,figure,figcaption,footer,header,hgroup,menu,nav,output,ruby,section,summary,time,mark,audio,video{margin:0;padding:0;border:0;font-size:100%;font:inherit;vertical-align:baseline;}
/* HTML5 display-role reset for older browsers */
article,aside,details,figcaption,figure,footer,header,hgroup,menu,nav,section{display:block;}body{line-height:1;display:block;}*{margin:0;padding:0;}html{display:block;}ol,ul{list-style:none;}blockquote,q{quotes:none;}blockquote:before,blockquote:after,q:before,q:after{content:&#39;&#39;;content:none;}table{border-collapse:collapse;border-spacing:0;}
/* FRAMEWORK */
#tab .quickedit img, .popular-posts .quickedit img {width: 18px!important;height:18px!important;padding: 0!important;border: 0!important;}
a.quickedit {background:transparent!important;}
.navbar,.post-feeds,.feed-links{display:none;
}
.section,.widget{margin:0 0 0 0;padding:0 0 0 0;
}
strong,b{font-weight:bold;
}
cite,em,i{font-style:italic;
}
a:link{color:#383838;text-decoration:none;outline:none;transition:all 0.25s;-moz-transition:all 0.25s;-webkit-transition:all 0.25s;
}
a:visited{color:#333333;text-decoration:none;
}
a:hover{color:$(maincolor);text-decoration:none;
}
a img{border:none;border-width:0;outline:none;
}
abbr,acronym{
}
sup,sub{vertical-align:baseline;position:relative;top:-.4em;font-size:86%;
}
sub{top:.4em;}small{font-size:86%;
}
kbd{font-size:80%;border:1px solid #999;padding:2px 5px;border-bottom-width:2px;border-radius:3px;
}
mark{background-color:#ffce00;color:black;
}
p,blockquote,pre,table,figure,hr,form,ol,ul,dl{margin:1.5em 0;
}
hr{height:1px;border:none;background-color:#666;
}
body#layout div#header-right {
width: 40%;
float: left;
}
/* heading */
h1,h2,h3,h4,h5,h6{font-weight:bold;line-height:normal;margin:0 0 0.6em;
}
h1{font-size:100%
}
h2{font-size:180%
}
h3{font-size:160%
}
h4{font-size:140%
}
h5{font-size:120%
}
h6{font-size:100%
}
/* list */
ol,ul,dl{margin:.5em 0em .5em 3em
}
ol{list-style:decimal outside
}
ul{list-style:disc outside
}
li{margin:.5em 0
}
dt{font-weight:bold
}
dd{margin:0 0 .5em 2em
}
/* form */
input,button,select,textarea{font:inherit;font-size:100%;line-height:normal;vertical-align:baseline;
}
textarea{display:block;-webkit-box-sizing:border-box;-moz-box-sizing:border-box;box-sizing:border-box;
}
/* code blockquote */
pre,code{font-family:&quot;Courier New&quot;,Courier,Monospace;color:inherit;
}
pre{white-space:pre;word-wrap:normal;overflow:auto;
}
.post-body blockquote {
background: url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEiozh427sFK9N7NEWCHbSVViztx9j46cNVQEVJOGN3HAFlRHnOglDGec2GH60etkbKZ7KgQoV3h9UXPPJeBEMgpfC7YrhqjHldbXI3RU5kD42WYUY-lZJc0gxu046ruRUxD_aotZkyEUQoX/s50/quote.png) no-repeat scroll left 18px transparent;
font-family: Georgia, serif;
font-size: 100%;
font-style: italic;
line-height: 22px;
margin: 20px 0 30px 20px;
min-height: 60px;
padding: 0 0 0 60px;
}
/* table */
.post-body table[border=&quot;1&quot;] th, .post-body table[border=&quot;1&quot;] td, .post-body table[border=&quot;1&quot;] caption{border:1px solid;padding:.2em .5em;text-align:left;vertical-align:top;
}
.post-body table.tr-caption-container {border:1px solid #e5e5e5;
}
.post-body th{font-weight:bold;
}
.post-body table[border=&quot;1&quot;] caption{border:none;font-style:italic;
}
.post-body table{
}
.post-body td, .post-body th{vertical-align:top;text-align:left;font-size:13px;padding:3px 5px;border:1px solid #e5e5e5;
}
.post-body th{background:#f0f0f0;
}
.post-body table.tr-caption-container td {border:none;padding:8px;
}
.post-body table.tr-caption-container, .post-body table.tr-caption-container img, .post-body img {max-width:100%;height:auto;
}
.post-body td.tr-caption {color:#666;font-size:80%;padding:0px 8px 8px !important;
}
img {
max-width:100%;
height:auto;
border:0;
}
table {
max-width:100%;
}
.post-timestamp {display: none;}
.clear {
clear:both;
}
.clear:after {
visibility:hidden;
display:block;
font-size:0;
content:" ";
clear:both;
height:0;
}


body#layout #mywrapper{
width: 60%;
float: left;
}


body#layout #post-wrapper {
width: 100%;
float: left;
}

body#layout div#main {
width: 100%;
}

body#layout #header-wrapper {
min-height: 0px;
margin-top: 70px;
background: #000000;

}

body {
margin: 0 0 0 0;
padding: 0 0 0 0;
text-align: left;
font-family: "Helvetica", Arial, sans-serif;
font-size: 14px;
line-height: 22px;
  background-color: #000000;
   background-color: #000000;
  background: url('https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEhU8s3VmZ8SLCUNLvhzn88kGG42XW0WcqV-kGFG_5UqyvXrTUx45wgsHjWfAzZVjm719Rs8VS8vYREgJJNAkfNqcVdg04dZwygI5pfn3AIm2qTBwjYqEexwl_ppKpKbmUAtaEI5JZ2N/s1600/111.jpg') fixed;
color: #494949;
word-wrap: break-word;
}
/* outer-wrapper */
#outer-wrapper {
background:#ffffff;
max-width:1200px;
margin:30px auto 0px;
overflow: hidden;
background: #fff;

}
/* NAVIGATION MENU */

div#top-nav {
background-color: #fafafa; 
height: 45px;
top: 0;
margin: 0 auto;

z-index: 9999;
border-left: 1px solid #e0e0e0;
border-right: 1px solid #e0e0e0;

-webkit-box-shadow: inset 0 1px 0 #fff, inset 0 -1px 0 #dadada, 0 0 15px rgba(0, 0, 0, 0.07);
-moz-box-shadow: inset 0 1px 0 #fff, inset 0 -1px 0 #dadada, 0 0 15px rgba(0, 0, 0, 0.07);
box-shadow: inset 0 1px 0 #fff, inset 0 -1px 0 #dadada, 0 0 15px rgba(0, 0, 0, 0.07);
}

.top-menu {
font:normal normal 12px Arial, sans-serif;
margin:0 auto;
height:45px;
overflow:hidden;

}
.top-menu1 {
font:normal normal 12px Arial, sans-serif;
margin:0 auto;
height:43px;
overflow:hidden;
padding: 0px 0px 0;
}
.menubar {
list-style-type:none;
margin:0 0 0 0;
padding:0 0 0 0;
}
.menubar li {
display: block;
float: left;
line-height: 46px;
margin: 0 0 0 0;
padding: 0 0 0 0;

}
.menubar li a {

padding: 0 12px;

line-height: 13px;
text-decoration: none;
text-transform: uppercase;
font-size: 13px;
text-transform: uppercase;
font-family: 'Open Sans', Arial, sans-serif;
font-weight: 300;
color: #333;
}
.menubar li a:hover {
color:#222;
}
ul.socialbar {
height: 44px;
margin: 0 0 0 0;
padding: 0 0;
float: right;
line-height: 43px;
background: #f6f6f6;

}

ul.socialbar a {
color: #333;
font-size: 24px;
padding: 5px 13px;
text-align: center;
border-left: 1px solid #e0e0e0;
-moz-box-shadow: inset 1px 0 0 #fff;
-webkit-box-shadow: inset 1px 0 0 #fff;
box-shadow: inset 1px 0 0 #fff;
}

ul.socialbar .fa{width: 20px;}
ul.socialbar li {
display:inline-block;
list-style-type:none;
float:right;
margin:0 0;
padding:0 0;
border-right:none;
}


/* HEADER WRAPPER */
#header-wrapper {
margin:0 auto;
overflow:hidden;
  padding: 30px 28px;
  background: #000000;
  min-height: 150px;
}
.header {
float: left;
  width: 27.7%;
  max-width: 277px;
  /* height: 110px; */
  margin: 12px 0;
}

div#header-inner {
margin-left: 10px;
}

.header h1.title,.header p.title {
font:normal bold 65px Fjalla One, Arial, Helvetica, sans-serif;
margin:0 0 0 0;
text-transform:uppercase;
  color: #fff;
}
.header .description {
color:#555555;
}
.header a {
color:#fff;
}
.header a:hover {
color:#999;
}
.header img {
display:block;
padding: 9px 0 39px;
}
.header-right {
float: right;
padding: 0;
overflow: hidden;
margin: 8px 0px 0 0;
width: 72.8%;
max-width: 728px;
max-height: 90px;
}
.header-right img {
display:block;
}
#nav {
  font: normal bold 12px Arial, sans-serif;

  height: 45px;
  top: 0;
  margin: -46px 28px 0;
  padding: 0;

  z-index: 9999;
  background: #3a3a3a;
  border-bottom: 1px solid #3a3a3a;

}
.menubar2 {
list-style: none;
margin:0 0 0 0;
*zoom: 1;
float:left;
}
.menubar2:before,
.menubar2:after {
content: " ";
display: table;
}
.menubar2:after {
clear: both;
}
.menubar2 ul {
list-style: none;
margin:0 0 0 0;
width:12em;
}
.menubar2 a {
display:block;
padding:0 15px;
}
.menubar2 li {
position: relative;
display: block;
float: left;
line-height: 45px;
margin: 0 0 0 0;
padding: 0 1px 0 0;
}
.menubar2 > li {
float: left;
}
.menubar2 > li > a {
display: block;
height: 45px;
line-height: 45px;
font-size: 15px;
text-transform: uppercase;
font-family: 'Open Sans', Arial, sans-serif;
font-weight: 300;
color: #FFFFFF;
}

.active {
  color: #FFFFFF!important;
  border-bottom: 1px solid #0D1C2E;
}

.active a{
color: #ddd!important;
}
.menubar2 > li:hover {
  background: #0D1C2E;
  color: #fff;
  border-bottom: 1px solid #0D1C2E;
}

.active:hover {
  color: #ddd!important;
  border-bottom:none;
}

.menubar2 li ul {
background: #383838;
border-bottom: 4px solid $(maincolor);
display:block;
position:absolute;
left:0;
z-index:10;
visibility:hidden;
opacity:0;
-webkit-transition:all .25s ease-out;
-moz-transition:all .25s ease-out;
-ms-transition:all .25s ease-out;
-o-transition:all .25s ease-out;
transition:all .25s ease-out;
}
.menubar2 li li ul {
left:100%;
top:-1px;
}
.menubar2 > li.hover > ul {
visibility:visible;
opacity:10;
}

.menubar2 li li.hover ul {
visibility:visible;
opacity:10;
}
.menubar2 li li a {
display: block;
color: #fff;
font-family: 'Droid Sans', sans-serif;
position: relative;
z-index: 100;
line-height: 32px;
border-bottom: 1px solid #313030;
}
.menubar2 li li a:hover {
color:#878787;
}
.menubar2 li li li a {
color: #e0dfdf;
font-family: 'Droid Sans', sans-serif;
text-shadow: 0 1px 1px #4B4B4B;
z-index:20;
}
i.fa.fa-home {
font-size: 25px;
padding: 10px 5px;
}
/* CONTENT WRAPPER */
#content-wrapper {
background-color:transparent;
margin: 0 auto;
padding: 0px 28px 0;
word-wrap:break-word;

}
div#featured-posts-section {
max-height: 400px;
overflow: hidden;
padding: 28px;
background-color: #fff;
}
.largebanner {
background:#fff;
border-right:1px solid #e5e5e5;
border-bottom:1px solid #e5e5e5;
border-left:1px solid #e5e5e5;
}
.largebanner .widget {
padding:15px 14px;
overflow:hidden;
}
.largebanner img, .largebanner iframe{
display:block;
max-width:100%;
border:none;
overflow:hidden;
}
/* POST WRAPPER */
#post-wrapper {
background:transparent;
float:left;
width:805px;
max-width:805px;
margin:0 0 10px;
border-right: 1px solid #E0E0E0;
}
.post-container {
padding:0px 0px 0 0;
}

.header h1.title:first-letter {
color: #0D1C2E;
}
.breadcrumbs {font-size: 13px;
line-height: 21px;
margin: 0 0 25px 0;
display: block;
overflow: hidden;
padding: 0 0 10px 0;
border-bottom: 1px solid #dfdfdf;}
.breadcrumbs > span {padding: 10px 5px 10px 10px;}
.breadcrumbs > span:last-child {background: none repeat scroll 0 0 transparent;color: #808080;}
.breadcrumbs a {color: #333333;}
.post {
background:#ffffff;
margin:0 0 15px;
padding:15px 0;

}
.post-body {
display: block;
margin: 0 0 0 0;
font-size: 16px;
line-height: 28px;
color: #585858;
}
h2.post-title, h1.post-title {
  margin-bottom: 2px;
  text-transform: none;
  font-family: sans-serif;
  font-weight: 400;
  font-style: normal;
  color: #444444;
  font-size: 1.25em;
}
h2.post-title a, h1.post-title a, h2.post-title, h1.post-title {
color:#383838;
}
h2.post-title a:hover, h1.post-title a:hover {
color:#0D1C2E;
}
.img-thumbnail {
background:#fbfbfb url(https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEi3XOehz5zkG1NPZ3BGUyDRxVXabbEVLUku_X71FFbEMzgnS2V-UwWESuRwfDrbEaw3Mvj6OTPCBdvTmRPlIOFn1qCb7b4HsX5Brj3YeDBVBIdKk6ypxkTd0McCA5fBMNs7iYkAAeS7uHFh/w200-c-h140/no-image.png) no-repeat center center;
position:relative;
float:left;
width:200px;
height:200px;
margin:0 25px 0 0;
}
.img-thumbnail img {
width:200px;
height:200px;
}
span.rollover {
}
span.rollover:before {
content:"";
position: absolute;
width:24px;
height:24px;
margin:-12px;
top:50%;
left:50%;
}
span.rollover:hover {
opacity: .7;
-o-transition:all 1s;
-moz-transition:all 1s;
-webkit-transition:all 1s;
}
.post-info {

  padding: 10px 0;

  color: #999;
  font-weight: 400;
  font-style: normal;
  font-family: sans-serif;
  font-size: 10px;
  line-height: 1em;
}
.post-info a {
display:inline-block;
color:#666666;
}
.author-info, .time-info, .comment-info, .label-info, .review-info {
margin-right:12px;
display:inline;
}

span.comment-info {
  float: right;
}
span.label-info a {
  font-size: 10px;
  letter-spacing: 1px;
  line-height: 1em;
  padding: 3px 4px;
  text-transform: uppercase;
  text-decoration: none;
  display: inline-block;
  margin-right: 4px;
  background-color: #0D1C2E;
  color: #fff;
  font-family: sans-serif;
  margin-bottom: 10px;
}

a.readmore {
display: inline-block;
margin: 15px 0 0;
background-color: #0D1C2E;
border: 1px solid #02A4E3;
padding: 0px 10px;
line-height: 26px;
color: #FFFFFF;
font-size: 11px;
font-weight: bold;
text-transform: uppercase;
}
a.readmore:hover  {
border:1px solid #aaaaaa;
}
/* Page Navigation */
.pagenavi {
clear: both;
margin: -16px 0 10px;
text-align: center;
font-size: 14px;
font-weight: bold;
padding: 0px;
text-transform: uppercase;
border-bottom: 1px solid #ddd;
border-top: 1px solid #ddd;
}
.pagenavi span,.pagenavi a {
padding: 6px 20px 6px 15px;
display:inline-block;
color:#1C2B3A;
float: left;
background: none repeat scroll 0 0 transparent;
border-right: 1px solid #DDDDDD;
background-color:#ffffff;
border: 1px solid #DDE2EA;
}
.pagenavi .current, .pagenavi .pages, .pagenavi a:hover {
background: #0D1C2E;
color: #fff;
}
.pagenavi .pages {
display:none;
}
/* SIDEBAR WRAPPER */
#sidebar-wrapper {
background:transparent;
float:right;
width:35%;
max-width:310px;
margin:0 auto;
}
.sidebar-container {
padding:15px 0;
}
.sidebar h2, .panel h2 {
display: block;
  font-family: 'Raleway',sans-serif;
  font-weight: 500;
  font-size: 20px;
  /* line-height: 22px; */
  padding: 5px 0 5px 0px;
  margin: 6px 0 5px 0;
  /* border-bottom: 3px #0D1C2E solid; */
  /* color: #222; */
  background: #333;
}
#sidebar1 h2 span,#sidebar h2 span{
}
.sidebar h2 span {
  /* padding-bottom: 12px; */
  background: #0D1C2E;
  color: #fff;
  padding: 5px 10px;
  /* border-bottom: 3px #444 solid; */
}

#bottombar h2 span {
bottom: -2px;
padding: 6px;
color: #fff;
}

.sidebar h2:after, .panel h2:after {
content: " ";
width:90px;
height: 0px;
position: absolute;
left: 0;
bottom: -2px;
}
.sidebar .widget {
margin:0 0 15px;
}
.sidebar ul, .sidebar ol {
list-style-type:none;
margin:0 0 0 0;
padding:0 0 0 0;
}
.sidebar li {
margin:5px 0;
padding:0 0 0 0;
}
/* Recent Post */
.recent-post-title {
margin:0 0 15px;
padding:0;
position:relative;
}
div.recent-post-title:after {

}
.recent-post-title h2 {
display: block;
font-family: 'Raleway',sans-serif;
font-weight: 500;
font-size: 24px;
line-height: 24px;
padding: 0 0 13px 0px;
margin: 6px 0 5px 0;
border-bottom: 3px $(maincolor) solid;
color: #222;
}
.recent-post-title h2 span{padding-bottom: 11px;
border-bottom: 3px #444 solid;}

.recent-post-title h2 a {
color:#474747;
}
.stylebox {
float:left;
width:50%;
margin:0 0;
}
.stylebox .widget {
padding:0 15px 15px 0;
}
.stylebox .widget-content {
background:#ffffff;
}
.stylebox ul {
list-style-type:none;
margin:0 0 0 0;
padding:0 0 0 0;
}
.stylebox1 {
float:left;
width:98%;
margin:0 0;
}
.stylebox1 .widget {
padding:0 0px 15px 0;
}
.stylebox1 .widget-content {
background:#ffffff;
}
.stylebox1  ul {
list-style-type:none;
margin:0 0 0 0;
padding:0 0 0 0;
}
/* Recent Post */
ul.xpose_thumbs {
margin:0 0 0 0;
}
ul.xpose_thumbs li {
font-size:12px;
min-height:68px;
margin:0 0 8px;
padding:0 0 8px;
border-bottom:1px dotted #e5e5e5;
}
ul.xpose_thumbs .xpose_thumb {
position:relative;
background:#fbfbfb;
margin:3px 0 10px 0;
width:100%;
height:50px;
padding-bottom:46%;
overflow:hidden;
}
ul.xpose_thumbs .xpose_thumb img {
height:auto;
width:100%;
}
ul.xpose_thumbs1 {
margin:0 0 0 0;
width:65%;
float:left;
}
ul.xpose_thumbs1 li {
font-size:12px;
min-height:68px;
margin:0 0 8px;
padding:0 0 8px;
border-bottom:1px dotted #e5e5e5;
}
ul.xpose_thumbs1 .xpose_thumb {
position:relative;
background:#fbfbfb;
margin:3px 0 10px 0;
width:100%;
height:62px;
padding-bottom:46%;
overflow:hidden;
}
ul.xpose_thumbs1 .xpose_thumb img {
height:auto;
width:100%;
}
ul.xpose_thumbs2 {
font-size:13px;
}
ul.xpose_thumbs2 li {
padding:0 0;
min-height:106px;
font-size:11px;
margin: 0 0 8px;
padding: 0 0 8px;
border-bottom:1px dotted #e5e5e5;
}
ul.xpose_thumbs2 .xpose_thumb2 {
background:#fbfbfb;
float:left;
margin:3px 8px 0 0;
height:100px;
width:100px;
}
ul.xpose_thumbs2 .xpose_thumb2 img {
height:100px;
width:100px;
}
span.xpose_title {
font-family: "Raleway",Helvetica,Arial,sans-serif;
font-size: 22px;
line-height: 24px;
font-weight: 500;
color: #222;
margin: 0 0 15px 0;
}
span.xpose_title2 {
font-size:16px;
}

span.xpose_title_big {
font-family: "Raleway",Helvetica,Arial,sans-serif;
font-size: 36px;
line-height: 40px;
font-weight: 400;
color: #222;
margin: 0 0 30px 0;
}

span.xpose_title22 {
font-size: 18px;
line-height: 24px;
font-weight: 500;
color: #222;
margin: 0 0 0 0;
}


span.rp_summary {
display: block;
margin: 0 0 0 0;
font-size: 16px;
line-height: 28px;
color: #585858;
}
span.xpose_meta {
background: transparent;
display: block;
font-size: 11px;
color: #aaa;
color: #aaa !important;

margin: 0px 0 0px 0;
font-size: 13px;
font-weight: 400;
line-height: 21px;

