body.script:
//
// Hamburger menu: toggles the nav panel on mobile, opens submenus on tap.
(function () {
  var nav = document.getElementById('nav');
  var toggle = document.getElementById('menu-toggle');
  var menu = document.getElementById('menu-main');
  if (!nav || !toggle || !menu) return;
  var mobile = window.matchMedia('(max-width: 1024px)');

  function setOpen(open) {
    if (open) nav.classList.add('nav-open'); else nav.classList.remove('nav-open');
    toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    toggle.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
  }

  function closeSubmenus() {
    var open = menu.querySelectorAll('li.open');
    for (var i = 0; i < open.length; i++) {
      open[i].classList.remove('open');
      var a = open[i].querySelector('a.parent');
      if (a) a.setAttribute('aria-expanded', 'false');
    }
  }

  toggle.addEventListener('click', function () {
    setOpen(!nav.classList.contains('nav-open'));
  });

  function onParentClick(e) {
    if (this.getAttribute('href') === '#') e.preventDefault();
    if (!mobile.matches) return;
    e.preventDefault();
    var li = this.parentNode;
    var open = !li.classList.contains('open');
    if (open) li.classList.add('open'); else li.classList.remove('open');
    this.setAttribute('aria-expanded', open ? 'true' : 'false');
  }

  var items = menu.getElementsByTagName('li');
  for (var i = 0; i < items.length; i++) {
    var link = null, sub = null;
    for (var c = items[i].firstElementChild; c; c = c.nextElementSibling) {
      if (c.tagName === 'A' && !link) link = c;
      if (c.tagName === 'UL') sub = c;
    }
    if (!link || !sub) continue;
    link.classList.add('parent');
    link.setAttribute('aria-haspopup', 'true');
    link.setAttribute('aria-expanded', 'false');
    link.addEventListener('click', onParentClick);
  }

  document.addEventListener('keydown', function (e) {
    if ((e.key === 'Escape' || e.key === 'Esc') && nav.classList.contains('nav-open')) {
      setOpen(false);
      toggle.focus();
    }
  });

  function onBreakpointChange() {
    if (!mobile.matches) {
      setOpen(false);
      closeSubmenus();
    }
  }
  if (mobile.addEventListener) mobile.addEventListener('change', onBreakpointChange);
  else if (mobile.addListener) mobile.addListener(onBreakpointChange);
})();
